# v342-N — Shudhūr al-Dhahab: where the app carries each of the 210 extracted rules (shudhur-al-dhahab-qawaid.jsonl).
# Each entry: eng = the engine (class · rule) that applies it, probes = the book's own examples with what the engine's line
# must say (letters only), na = why it is not automatable, note = a grammar note that carries it (checked by build_ledger.py).
# A rule is «applied» only when every probe passes in the page (build_ledger.py --prove, and the smoke check re-proves it).
def P(s, w, re, nt=None):
    d = {'s': s, 'w': w, 're': re}
    if nt: d['not'] = nt
    return d

